104	/**
105	 * Saves the settings being changed, leaving the others as they are: a figure setting's value is
106	 * recorded from its from-date (the sheet's today when none is given), keeping the values recorded
107	 * from other dates and replacing one recorded from the same date. An action's entry in the
108	 * permission matrix is not dated: it replaces the one before.
109	 */
110	public class SaveSettings {
111	    public void save(@Val SettingsInput input, @Val Sheet sheet, SettingsRepository repository,
112	            Out<Settings> settingsOut) {
113	        Settings now = repository.find(sheet.id());
114	        if (input.policyDateChanged() || input.periodNumberingFromChanged() || input.graceDaysChanged()
115	                || input.entryDateChanged() || input.potChanged()) {
116	            repository.saveUndated(new Settings(sheet.id(), now.today(), now.dated(),
117	                    input.policyDateChanged() ? input.policyDate() : now.policyDate(),
118	                    input.periodNumberingFromChanged() ? input.periodNumberingFrom() : now.periodNumberingFrom(), now.perms(),
119	                    input.graceDaysChanged() ? input.graceDays() : now.graceDays(),
120	                    input.entryDateChanged() ? input.entryDate() : now.entryDate(),
121	                    input.potChanged() ? input.pot() : now.pot()));
122	        }
123	        input.perms().forEach((action, roles) -> repository.recordPerm(sheet.id(), action, roles));
124	        java.util.Map<String, String> values = new java.util.LinkedHashMap<>(input.datedValues());
125	        values.putAll(input.gradeTermsValues());
126	        values.putAll(input.gradeGraceValues());
127	        values.putAll(input.gradeProofThresholdValues());
128	        if (input.capValue() != null) values.put(Settings.CAP, input.capValue());
129	        if (input.proofThresholdValue() != null) values.put(Settings.PROOF_THRESHOLD, input.proofThresholdValue());
130	        if (input.noteThresholdValue() != null) values.put(Settings.NOTE_THRESHOLD, input.noteThresholdValue());
131	        values.forEach((key, value) -> {
132	            LocalDate from = input.from().getOrDefault(key, sheet.today());
133	            repository.record(sheet.id(), key, from, value);
134	        });
135	        settingsOut.set(repository.find(sheet.id()));
136	    }
137	}
