228	/**
229	 * A sheet's settings. The figure settings are dated ({@code dated}, by key, each value from a
230	 * from-date; a blank value is "none"): its clerk limit, the highest due a clerk may settle (none: no
231	 * limit), its floor, the least a claim's live due may be, and its terms, the days after a claim's
232	 * date that it is due by, and its late percent, what an overdue claim's due gains per full 30 days
233	 * overdue, and its terms per grade (a grade with none uses the sheet's terms), and its cap (none:
234	 * no cap), the most a person's due-total may be, and its proof threshold (none: none), above which a
235	 * claim's due, on the claim's date, needs a proof before it is settled or approved, and its note
236	 * threshold (none: none), above which a claim's due, on the claim's date, needs a note before it is opened, and
237	 * its proof threshold per grade (none: the sheet's proof threshold). The value in force on a date is the one with the
238	 * latest from-date on or before it; before every from-date the starting value (floor 1.00, late
239	 * percent 0.00, terms 14; none for the others). A claim takes its floor, late percent and terms on
240	 * its date; the clerk limit and the cap are those in force on the sheet's today ({@code today}).
241	 * Not dated: its policy date (null: the sheet's today): a claim dated before it rounds half up, one
242	 * on or after it half to even, and its period numbering from (null: off): while the sheet's today
243	 * is on or after it, a claim opened is numbered within its period, and its permission matrix
244	 * ({@code perms}, by action, the roles that may take it as a comma separated list; blank or missing:
245	 * the standing rule, open, settle, void and close by clerk and steward, reassign and reopen by steward),
246	 * and its grace days (null: off): when the sheet's today is changed, every open period whose to-date
247	 * plus the grace days is before the new today is closed, and its entry date (null: off): while it is
248	 * set, the date of a new claim left undated instead of the sheet's today, and its pot (null: none),
249	 * shared out as cuts among a balanced pool's members.
250	 */
251	public record Settings(String sheetId, LocalDate today, Map<String, NavigableMap<LocalDate, String>> dated,
252	        LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, String> perms, Integer graceDays,
253	        LocalDate entryDate, BigDecimal pot) {
254	    /** The grades that may have their own terms. */
255	    public static final List<String> GRADES = List.of("A", "B", "C");
256	
257	    public static final String CLERK_LIMIT = "clerk-limit";
258	    public static final String FLOOR = "floor";
259	    public static final String TERMS = "terms";
260	    public static final String LATE_PCT = "late-pct";
261	    public static final String CAP = "cap";
262	    public static final String PROOF_THRESHOLD = "proof-threshold";
263	    public static final String NOTE_THRESHOLD = "note-threshold";
264	
265	    /** The actions of the permission matrix, in the order they are shown and audited. */
266	    public static final List<String> ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");
267	
268	    /** The key of an action's entry in the permission matrix. */
269	    public static String permKey(String action) {
270	        return "perm-" + action;
271	    }
272	
273	    /** The roles that may take an action by the standing rule. */
274	    public static List<String> standingRoles(String action) {
275	        return "reassign".equals(action) || "reopen".equals(action) ? List.of("steward") : List.of("clerk", "steward");
276	    }
277	
278	    /** The roles that may take an action: its entry in the permission matrix, else the standing rule. */
279	    public List<String> rolesFor(String action) {
280	        String entry = perms == null ? null : perms.get(action);
281	        if (entry == null || entry.isBlank()) return standingRoles(action);
282	        return java.util.Arrays.stream(entry.split(",")).map(String::trim).filter((r) -> !r.isEmpty()).toList();
283	    }
284	
285	    /** Whether a role may take an action. */
286	    public boolean allows(String action, String role) {
287	        if (net.officefloor.hq.app.role.Role.VIEWER.equals(role)) return false; // a viewer changes nothing
288	        return rolesFor(action).contains(role);
289	    }
290	
291	    /** The key of a grade's own terms. */
292	    public static String gradeTermsKey(String grade) {
293	        return "terms-" + grade;
294	    }
295	
296	    /** The key of a grade's grace days. */
297	    public static String gradeGraceKey(String grade) {
298	        return "grace-" + grade;
299	    }
300	
301	    /** The key of a grade's own proof threshold. */
302	    public static String gradeProofThresholdKey(String grade) {
303	        return "proof-threshold-" + grade;
304	    }
305	
306	    /** A grade's own proof threshold in force on a date, or null when it has none. */
307	    public BigDecimal gradeProofThresholdOn(String grade, LocalDate date) {
308	        return figureOn(gradeProofThresholdKey(grade), date);
309	    }
310	
311	    /** A grade's grace days in force on a date, or null when it has none. */
312	    public Integer gradeGraceOn(String grade, LocalDate date) {
313	        String value = valueOn(gradeGraceKey(grade), date);
314	        return value == null || value.isEmpty() ? null : Integer.valueOf(value);
315	    }
316	
317	    /**
318	     * The day a claim's overdue count starts from: its due-by plus the grace days of its grade (the
319	     * one in force on its date) in force on its date, or its due-by when that grade has none. A
320	     * claim is overdue when this is before the sheet's today, and its late charge's 30-day
321	     * boundaries are counted from it.
322	     */
323	    public LocalDate overdueFrom(LocalDate dueBy, String grade, LocalDate date) {
324	        Integer grace = grade == null ? null : gradeGraceOn(grade, date);
325	        return grace == null ? dueBy : dueBy.plusDays(grace);
326	    }
327	
328	    /** A sheet's floor until it is set. */
329	    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");
330	
331	    /** A sheet's terms until they are set. */
332	    public static final int DEFAULT_TERMS = 14;
333	
334	    /** A sheet's late percent until it is set. */
335	    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");
336	
337	    /** The value of a key in force on a date: null when none is recorded on or before it, '' for none. */
338	    public String valueOn(String key, LocalDate date) {
339	        NavigableMap<LocalDate, String> values = dated.get(key);
340	        if (values == null || date == null) return null;
341	        Map.Entry<LocalDate, String> entry = values.floorEntry(date);
342	        return entry == null ? null : entry.getValue();
343	    }
344	
345	    private BigDecimal figureOn(String key, LocalDate date) {
346	        String value = valueOn(key, date);
347	        return value == null || value.isEmpty() ? null : new BigDecimal(value).setScale(2);
348	    }
349	
350	    /** The floor in force on a date. */
351	    public BigDecimal floorOn(LocalDate date) {
352	        BigDecimal floor = figureOn(FLOOR, date);
353	        return floor != null ? floor : DEFAULT_FLOOR;
354	    }
355	
356	    /** The late percent in force on a date. */
357	    public BigDecimal latePctOn(LocalDate date) {
358	        BigDecimal pct = figureOn(LATE_PCT, date);
359	        return pct != null ? pct : DEFAULT_LATE_PCT;
360	    }
361	
362	    /** The sheet's terms in force on a date. */
363	    public int termsOn(LocalDate date) {
364	        String value = valueOn(TERMS, date);
365	        return value == null || value.isEmpty() ? DEFAULT_TERMS : Integer.parseInt(value);
366	    }
367	
368	    /** A grade's own terms in force on a date, or null when it takes the sheet's. */
369	    public Integer gradeTermsOn(String grade, LocalDate date) {
370	        String value = valueOn(gradeTermsKey(grade), date);
371	        return value == null || value.isEmpty() ? null : Integer.valueOf(value);
372	    }
373	
374	    /** The terms of a person's claim on a date: their own, else their grade's then, else the sheet's. */
375	    public int termsFor(net.officefloor.hq.app.person.Person person, LocalDate date) {
376	        Integer own = person.getTerms();
377	        return own != null ? own : termsFor(person.gradeOn(date), date);
378	    }
379	
380	    /** The terms of a grade on a date: its own, else the sheet's. */
381	    public int termsFor(String grade, LocalDate date) {
382	        Integer own = gradeTermsOn(grade, date);
383	        return own != null ? own : termsOn(date);
384	    }
385	
386	    /** The clerk limit in force on a date (null: no limit). */
387	    public BigDecimal clerkLimitOn(LocalDate date) {
388	        return figureOn(CLERK_LIMIT, date);
389	    }
390	
391	    /** The proof threshold in force on a date (null: none). */
392	    public BigDecimal proofThresholdOn(LocalDate date) {
393	        return figureOn(PROOF_THRESHOLD, date);
394	    }
395	
396	    /**
397	     * The proof threshold of a claim of a grade dated {@code date}: the grade's own in force on that
398	     * date when it has one, else the sheet's (null: none).
399	     */
400	    public BigDecimal proofThresholdFor(String grade, LocalDate date) {
401	        BigDecimal own = grade == null ? null : gradeProofThresholdOn(grade, date);
402	        return own != null ? own : proofThresholdOn(date);
403	    }
404	
405	    /**
406	     * Whether a claim of a grade dated {@code date} with a due (null: n/a) and a proofs count needs
407	     * a proof before it is settled or approved: its due is above its proof threshold and it has no
408	     * proofs. A due of n/a, or no threshold, needs none.
409	     */
410	    public boolean needsProof(BigDecimal due, String grade, LocalDate date, int proofs) {
411	        BigDecimal threshold = proofThresholdFor(grade, date);
412	        return proofs == 0 && threshold != null && due != null && due.compareTo(threshold) > 0;
413	    }
414	
415	    /** The note threshold in force on a date (null: none). */
416	    public BigDecimal noteThresholdOn(LocalDate date) {
417	        return figureOn(NOTE_THRESHOLD, date);
418	    }
419	
420	    /**
421	     * Whether a claim dated {@code date} with a due (null: n/a) and a note needs a note before it is
422	     * opened: its due is above the note threshold in force on its date and its note is empty. A due
423	     * of n/a, or no threshold, needs none.
424	     */
425	    public boolean needsNote(BigDecimal due, LocalDate date, String note) {
426	        BigDecimal threshold = noteThresholdOn(date);
427	        return (note == null || note.isBlank()) && threshold != null && due != null && due.compareTo(threshold) > 0;
428	    }
429	
430	    /** The cap in force on a date (null: none). */
431	    public BigDecimal capOn(LocalDate date) {
432	        return figureOn(CAP, date);
433	    }
434	
435	    /**
436	     * How every figure of a claim that rounds by {@code date} is rounded: half up before the policy
437	     * date ({@code today} when it is blank), half to even on or after it.
438	     */
439	    public RoundingMode rounding(LocalDate date, LocalDate today) {
440	        LocalDate policy = policyDate != null ? policyDate : today;
441	        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
442	    }
443	
444	    /** The date of a new claim left undated: the entry date while it is set, else the sheet's today. */
445	    public LocalDate entryDay(LocalDate today) {
446	        return entryDate != null ? entryDate : today;
447	    }
448	
449	    /** Whether a period ending {@code to} is past its grace days on {@code today}: never while they are off. */
450	    public boolean pastGrace(LocalDate to, LocalDate today) {
451	        return graceDays != null && to.plusDays(graceDays).isBefore(today);
452	    }
453	
454	    /** Whether a claim opened on {@code today} is numbered within its period. */
455	    public boolean numbersByPeriod(LocalDate today) {
456	        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
457	    }
458	
459	    /** A person's due-total (null: n/a) held to the cap in force on {@code today}. A due-total of n/a is not capped. */
460	    public BigDecimal capped(BigDecimal dueTotal, LocalDate today) {
461	        BigDecimal cap = capOn(today);
462	        return cap == null || dueTotal == null || dueTotal.compareTo(cap) <= 0 ? dueTotal : cap;
463	    }
464	
465	    /** Whether a due (null: n/a) is within the clerk limit in force on {@code today}. A due of n/a is within any limit. */
466	    public boolean withinClerkLimit(BigDecimal due, LocalDate today) {
467	        BigDecimal clerkLimit = clerkLimitOn(today);
468	        return clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
469	    }
470	}
