487	    private final JdbcTemplate jdbc;
488	
489	    public SettingsRepository(JdbcTemplate jdbc) {
490	        this.jdbc = jdbc;
491	    }
492	
493	    public Settings find(String sheetId) {
494	        Map<String, NavigableMap<LocalDate, String>> dated = new HashMap<>();
495	        jdbc.query("SELECT setting_key, from_date, setting_value FROM setting_value WHERE sheet_id = ?",
496	                (RowCallbackHandler) (rs) -> dated.computeIfAbsent(rs.getString("setting_key"), (k) -> new TreeMap<>())
497	                        .put(rs.getDate("from_date").toLocalDate(), rs.getString("setting_value")), sheetId);
498	        Map<String, String> perms = new HashMap<>();
499	        jdbc.query("SELECT action, roles FROM setting_perm WHERE sheet_id = ?",
500	                (RowCallbackHandler) (rs) -> perms.put(rs.getString("action"), rs.getString("roles")), sheetId);
501	        List<Settings> found = jdbc.query("SELECT today, policy_date, period_numbering_from, grace_days, entry_date, pot FROM sheet WHERE id = ?",
502	                (rs, n) -> new Settings(sheetId, rs.getDate("today").toLocalDate(), dated,
503	                        rs.getDate("policy_date") == null ? null : rs.getDate("policy_date").toLocalDate(),
504	                        rs.getDate("period_numbering_from") == null ? null : rs.getDate("period_numbering_from").toLocalDate(), perms,
505	                        rs.getObject("grace_days", Integer.class),
506	                        rs.getDate("entry_date") == null ? null : rs.getDate("entry_date").toLocalDate(),
507	                        rs.getBigDecimal("pot")),
508	                sheetId);
509	        return found.isEmpty() ? new Settings(sheetId, null, dated, null, null, perms, null, null, null) : found.get(0);
510	    }
511	
512	    /** Records a dated setting's value from a date, replacing any value already recorded from it. */
513	    public void record(String sheetId, String key, LocalDate from, String value) {
514	        jdbc.update("MERGE INTO setting_value (sheet_id, setting_key, from_date, setting_value) KEY (sheet_id, setting_key, from_date) VALUES (?, ?, ?, ?)",
515	                sheetId, key, java.sql.Date.valueOf(from), value);
516	        history(sheetId, key, from, value);
517	    }
518	
519	    /** Keeps a setting's value in its history, with the sheet's today now. */
520	    private void history(String sheetId, String key, LocalDate from, String value) {
521	        jdbc.update("INSERT INTO setting_history (sheet_id, setting_key, from_date, setting_value, set_on)"
522	                + " VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
523	                sheetId, key, from == null ? null : java.sql.Date.valueOf(from), value, sheetId);
524	    }
525	
526	    /**
527	     * The sheet's settings as they stood at the end of {@code day}: each dated value and the policy
528	     * date as last recorded while the sheet's today was on or before it, and that date standing in for
529	     * the sheet's today. The others are as they are now.
530	     */
531	    public Settings findAsOf(String sheetId, LocalDate day) {
532	        Settings now = find(sheetId);
533	        Map<String, NavigableMap<LocalDate, String>> dated = new HashMap<>();
534	        LocalDate[] policy = { null };
535	        boolean[] policyKept = { false };
536	        jdbc.query("SELECT setting_key, from_date, setting_value, set_on FROM setting_history WHERE sheet_id = ? ORDER BY id",
537	                (RowCallbackHandler) (rs) -> {
538	                    String key = rs.getString("setting_key");
539	                    String value = rs.getString("setting_value");
540	                    boolean counts = !rs.getDate("set_on").toLocalDate().isAfter(day);
541	                    if (POLICY_DATE.equals(key)) {
542	                        policyKept[0] = true;
543	                        if (counts) policy[0] = value.isBlank() ? null : LocalDate.parse(value);
544	                    } else if (counts) {
545	                        dated.computeIfAbsent(key, (k) -> new TreeMap<>()).put(rs.getDate("from_date").toLocalDate(), value);
546	                    }
547	                }, sheetId);
548	        return new Settings(sheetId, day, dated, policyKept[0] ? policy[0] : now.policyDate(),
549	                now.periodNumberingFrom(), now.perms(), now.graceDays(), now.entryDate(), now.pot());
550	    }
551	
552	    private static final String POLICY_DATE = "policy-date";
553	
554	    /** Records the roles ('' for the standing rule) that may take an action. */
555	    public void recordPerm(String sheetId, String action, String roles) {
556	        jdbc.update("MERGE INTO setting_perm (sheet_id, action, roles) KEY (sheet_id, action) VALUES (?, ?, ?)",
557	                sheetId, action, roles);
558	    }
559	
560	    /** Saves the undated settings. */
561	    public void saveUndated(Settings settings) {
562	        jdbc.update("UPDATE sheet SET policy_date = ?, period_numbering_from = ?, grace_days = ?, entry_date = ?, pot = ? WHERE id = ?",
563	                settings.policyDate() == null ? null : java.sql.Date.valueOf(settings.policyDate()),
564	                settings.periodNumberingFrom() == null ? null : java.sql.Date.valueOf(settings.periodNumberingFrom()),
565	                settings.graceDays(),
566	                settings.entryDate() == null ? null : java.sql.Date.valueOf(settings.entryDate()),
567	                settings.pot(), settings.sheetId());
568	        history(settings.sheetId(), POLICY_DATE, null,
569	                settings.policyDate() == null ? "" : settings.policyDate().toString());
570	    }
571	}
