619	public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate,
620	        String periodNumberingFrom, Map<String, String> gradeTerms, String cap, Map<String, List<Dated>> dated,
621	        String proofThreshold, Map<String, String> perms, String graceDays, String noteThreshold,
622	        String entryDate, Map<String, String> gradeGrace, Map<String, String> gradeProofThreshold,
623	        String pot) {
624	
625	    /** A value ('' for none) recorded from a date (yyyy-MM-dd). */
626	    public record Dated(String from, String value) {
627	    }
628	
629	    public static SettingsResponse from(Settings settings) {
630	        LocalDate today = settings.today();
631	        return new SettingsResponse(show(settings.clerkLimitOn(today)),
632	                show(settings.floorOn(today)), Integer.toString(settings.termsOn(today)),
633	                show(settings.latePctOn(today)),
634	                settings.policyDate() == null ? "" : settings.policyDate().toString(),
635	                settings.periodNumberingFrom() == null ? "" : settings.periodNumberingFrom().toString(),
636	                gradeTerms(settings),
637	                show(settings.capOn(today)),
638	                dated(settings),
639	                show(settings.proofThresholdOn(today)),
640	                perms(settings),
641	                settings.graceDays() == null ? "" : settings.graceDays().toString(),
642	                show(settings.noteThresholdOn(today)),
643	                settings.entryDate() == null ? "" : settings.entryDate().toString(),
644	                gradeGrace(settings),
645	                gradeProofThreshold(settings),
646	                show(settings.pot()));
647	    }
648	
649	    private static String show(java.math.BigDecimal figure) {
650	        return figure == null ? "" : figure.setScale(2).toPlainString();
651	    }
652	
653	    private static Map<String, String> gradeTerms(Settings settings) {
654	        Map<String, String> shown = new LinkedHashMap<>();
655	        for (String grade : Settings.GRADES) {
656	            Integer own = settings.gradeTermsOn(grade, settings.today());
657	            shown.put(grade, own == null ? "" : own.toString());
658	        }
659	        return shown;
660	    }
661	
662	    private static Map<String, String> gradeGrace(Settings settings) {
663	        Map<String, String> shown = new LinkedHashMap<>();
664	        for (String grade : Settings.GRADES) {
665	            Integer grace = settings.gradeGraceOn(grade, settings.today());
666	            shown.put(grade, grace == null ? "" : grace.toString());
667	        }
668	        return shown;
669	    }
670	
671	    private static Map<String, String> gradeProofThreshold(Settings settings) {
672	        Map<String, String> shown = new LinkedHashMap<>();
673	        for (String grade : Settings.GRADES) shown.put(grade, show(settings.gradeProofThresholdOn(grade, settings.today())));
674	        return shown;
675	    }
676	
677	    private static Map<String, String> perms(Settings settings) {
678	        Map<String, String> shown = new LinkedHashMap<>();
679	        for (String action : Settings.ACTIONS) {
680	            String roles = settings.perms() == null ? null : settings.perms().get(action);
681	            shown.put(action, roles == null ? "" : roles);
682	        }
683	        return shown;
684	    }
685	
686	    private static Map<String, List<Dated>> dated(Settings settings) {
687	        Map<String, List<Dated>> shown = new LinkedHashMap<>();
688	        settings.dated().forEach((key, values) -> {
689	            List<Dated> list = new ArrayList<>();
690	            values.forEach((from, value) -> list.add(new Dated(from.toString(), value)));
691	            shown.put(key, list);
692	        });
693	        return shown;
694	    }
