852	        Map<String, String> perms = new LinkedHashMap<>();
853	        if (request != null && request.perms() != null) {
854	            for (String action : request.perms().keySet()) {
855	                if (!Settings.ACTIONS.contains(action)) {
856	                    throw new InvalidSettingException("An action is one of " + String.join(", ", Settings.ACTIONS));
857	                }
858	            }
859	            for (String action : Settings.ACTIONS) {
860	                String value = request.perms().get(action);
861	                if (value == null) continue;
862	                value = value.trim();
863	                java.util.List<String> roles = new java.util.ArrayList<>();
864	                if (!value.isEmpty()) {
865	                    for (String role : value.split(",", -1)) {
866	                        role = role.trim();
867	                        if (!Role.CLERK.equals(role) && !Role.STEWARD.equals(role)) {
868	                            throw new InvalidSettingException("Roles are clerk or steward, separated by commas, or blank");
869	                        }
870	                        if (!roles.contains(role)) roles.add(role);
871	                    }
872	                }
873	                perms.put(action, String.join(",", roles));
874	            }
875	        }
876	        boolean graceChanged = request != null && request.graceDays() != null;
877	        Integer graceDays = null;
878	        if (graceChanged && !request.graceDays().trim().isEmpty()) {
879	            String value = request.graceDays().trim();
880	            if (!DAYS.matcher(value).matches()) {
881	                throw new InvalidSettingException("Grace days are a whole number of days, 0 or more, or blank");
882	            }
883	            graceDays = Integer.valueOf(value);
884	        }
885	        boolean entryChanged = request != null && request.entryDate() != null;
886	        LocalDate entryDate = null;
887	        if (entryChanged && !request.entryDate().trim().isEmpty()) {
888	            try {
889	                entryDate = LocalDate.parse(request.entryDate().trim());
890	            } catch (DateTimeParseException e) {
891	                throw new InvalidSettingException("An entry date is a date, yyyy-MM-dd, or blank");
892	            }
893	        }
894	        boolean potChanged = request != null && request.pot() != null;
895	        BigDecimal pot = null;
896	        if (potChanged && !request.pot().trim().isEmpty()) {
897	            String value = request.pot().trim();
898	            if (!FIGURE.matcher(value).matches()) {
899	                throw new InvalidSettingException("A pot is 0.00 or more, with up to two decimals, or blank");
900	            }
901	            pot = new BigDecimal(value).setScale(2);
902	        }
903	        Map<String, LocalDate> from = new LinkedHashMap<>();
904	        if (request != null && request.from() != null) {
905	            for (Map.Entry<String, String> entry : request.from().entrySet()) {
906	                if (!DATED.contains(entry.getKey())) throw new InvalidSettingException("Only a figure setting has a from-date");
907	                String value = entry.getValue() == null ? "" : entry.getValue().trim();
908	                if (value.isEmpty()) continue;
909	                try {
910	                    from.put(entry.getKey(), LocalDate.parse(value));
911	                } catch (DateTimeParseException e) {
912	                    throw new InvalidSettingException("A from-date is a date, yyyy-MM-dd, or blank");
913	                }
914	            }
915	        }
916	        body.set(new SettingsInput(limitChanged, limit, floor, terms, latePct, policyChanged, policyDate,
917	                numberingChanged, numberingFrom, gradeTerms, capChanged, cap, from,
918	                thresholdChanged, threshold, perms, graceChanged, graceDays, noteThresholdChanged, noteThreshold,
919	                entryChanged, entryDate, gradeGrace, gradeProofThreshold, potChanged, pot));
920	    }
921	}
922	# Save a sheet's settings. Validate first so a bad value is a 400, not a 404.
923	# A viewer may change nothing: refused before anything is read or written.
924	viewer:
925	  class: net.officefloor.hq.app.role.CheckCanChange
926	  next: validate
927	validate:
928	  class: net.officefloor.hq.app.setting.ValidateSettings
929	  next: load
930	load:
931	  class: net.officefloor.hq.app.sheet.LoadSheet
932	  govern: [ transaction ]
933	  next: before
934	# The sheet's figures before the change, so the rollup lines tell which moved (the floor moves them).
935	before:
936	  class: net.officefloor.hq.app.rollup.TakeRollup
937	  govern: [ transaction ]
938	  next: save
939	save:
940	  class: net.officefloor.hq.app.setting.SaveSettings
941	  govern: [ transaction ]
942	  next: audit
943	# Last before the response: every rule has passed and the change is saved.
944	audit:
945	  class: net.officefloor.hq.app.setting.AuditSettingChanged
946	  govern: [ transaction ]
947	  next: rollup
948	# After the change's own lines: the figures it moved.
949	rollup:
950	  class: net.officefloor.hq.app.rollup.AuditRollup
951	  govern: [ transaction ]
952	  next: respond
953	respond:
954	  class: net.officefloor.hq.app.setting.RespondWithSettings
955	  govern: [ transaction ]
