package net.officefloor.hq.app.setting;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/**
 * Records each setting saved, with the value saved (blank for no clerk limit): the clerk limit, then
 * the floor, then the terms, then the late percent, then the policy date, then the period numbering
 * from, then each grade's terms (blank for the sheet's), then the cap (blank for none), then the proof threshold (blank for none), then the note threshold (blank for none), then each
 * action's entry in the permission matrix (blank for the standing rule, never dated), then the grace
 * days (blank for off, never dated), then the entry date (blank for off, never dated), then each
 * grade's grace days (blank for none), then each grade's proof threshold (blank for none), then the pot
 * (blank for none, never dated); a figure
 * setting saved from a from-date given ends with it. Runs after every rule has passed, so a refused
 * change writes nothing.
 */
public class AuditSettingChanged {
    public void audit(@Val Sheet sheet, @Val SettingsInput input, @Val Settings settings,
            HttpServletRequest request, Audit audit) {
        String head = "SETTING_CHANGED sheet=" + sheet.id() + " by=" + Audit.user(request);
        input.datedValues().forEach((key, value) -> audit.record(line(head, key, value, input)));
        if (input.policyDateChanged()) {
            audit.record(head + " key=policy-date value=" + (input.policyDate() == null ? "" : input.policyDate()));
        }
        if (input.periodNumberingFromChanged()) {
            audit.record(head + " key=period-numbering-from value="
                    + (input.periodNumberingFrom() == null ? "" : input.periodNumberingFrom()));
        }
        input.gradeTermsValues().forEach((key, value) -> audit.record(line(head, key, value, input)));
        if (input.capValue() != null) audit.record(line(head, Settings.CAP, input.capValue(), input));
        if (input.proofThresholdValue() != null) {
            audit.record(line(head, Settings.PROOF_THRESHOLD, input.proofThresholdValue(), input));
        }
        if (input.noteThresholdValue() != null) {
            audit.record(line(head, Settings.NOTE_THRESHOLD, input.noteThresholdValue(), input));
        }
        input.perms().forEach((action, roles) -> audit.record(head + " key=" + Settings.permKey(action) + " value=" + roles));
        if (input.graceDaysChanged()) {
            audit.record(head + " key=grace-days value=" + (input.graceDays() == null ? "" : input.graceDays()));
        }
        if (input.entryDateChanged()) {
            audit.record(head + " key=entry-date value=" + (input.entryDate() == null ? "" : input.entryDate()));
        }
        input.gradeGraceValues().forEach((key, value) -> audit.record(line(head, key, value, input)));
        input.gradeProofThresholdValues().forEach((key, value) -> audit.record(line(head, key, value, input)));
        if (input.potChanged()) {
            audit.record(head + " key=pot value=" + (input.pot() == null ? "" : input.pot().toPlainString()));
        }
    }

    private static String line(String head, String key, String value, SettingsInput input) {
        LocalDate from = input.from().get(key);
        return head + " key=" + key + " value=" + value + (from == null ? "" : " from=" + from);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidSetting {
    public void handle(@Parameter InvalidSettingException ex,
            ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.setting;

/** A clerk limit that is neither blank nor a figure of 0.00 or more with up to two decimals. */
public class InvalidSettingException extends Exception {
    public InvalidSettingException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.setting;

import jakarta.servlet.http.HttpServletRequest;
import java.time.LocalDate;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** The sheet's settings; read as of a date, as they stood then. */
public class RespondWithSettings {
    public void respond(@Val Sheet sheet, SettingsRepository repository, HttpServletRequest request,
            ObjectResponse<SettingsResponse> response) {
        LocalDate asOf = AsOf.of(request);
        response.send(SettingsResponse.from(asOf == null ? repository.find(sheet.id()) : repository.findAsOf(sheet.id(), asOf)));
    }
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Saves the settings being changed, leaving the others as they are: a figure setting's value is
 * recorded from its from-date (the sheet's today when none is given), keeping the values recorded
 * from other dates and replacing one recorded from the same date. An action's entry in the
 * permission matrix is not dated: it replaces the one before.
 */
public class SaveSettings {
    public void save(@Val SettingsInput input, @Val Sheet sheet, SettingsRepository repository,
            Out<Settings> settingsOut) {
        Settings now = repository.find(sheet.id());
        if (input.policyDateChanged() || input.periodNumberingFromChanged() || input.graceDaysChanged()
                || input.entryDateChanged() || input.potChanged()) {
            repository.saveUndated(new Settings(sheet.id(), now.today(), now.dated(),
                    input.policyDateChanged() ? input.policyDate() : now.policyDate(),
                    input.periodNumberingFromChanged() ? input.periodNumberingFrom() : now.periodNumberingFrom(), now.perms(),
                    input.graceDaysChanged() ? input.graceDays() : now.graceDays(),
                    input.entryDateChanged() ? input.entryDate() : now.entryDate(),
                    input.potChanged() ? input.pot() : now.pot()));
        }
        input.perms().forEach((action, roles) -> repository.recordPerm(sheet.id(), action, roles));
        java.util.Map<String, String> values = new java.util.LinkedHashMap<>(input.datedValues());
        values.putAll(input.gradeTermsValues());
        values.putAll(input.gradeGraceValues());
        values.putAll(input.gradeProofThresholdValues());
        if (input.capValue() != null) values.put(Settings.CAP, input.capValue());
        if (input.proofThresholdValue() != null) values.put(Settings.PROOF_THRESHOLD, input.proofThresholdValue());
        if (input.noteThresholdValue() != null) values.put(Settings.NOTE_THRESHOLD, input.noteThresholdValue());
        values.forEach((key, value) -> {
            LocalDate from = input.from().getOrDefault(key, sheet.today());
            repository.record(sheet.id(), key, from, value);
        });
        settingsOut.set(repository.find(sheet.id()));
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Validated settings, each scaled to two decimals: whether the clerk limit is changed and to what
 * (null: no limit), the floor (null: left as it is) the terms in days (null: left as they are) and the late percent (null: left as it is),
 * and whether the policy date is changed and to what (null: the sheet's today), and whether the
 * period numbering from is changed and to what (null: off), and the grades whose terms are changed,
 * in A, B, C order, and to what (null: the sheet's terms), and whether the cap is changed and to
 * what (null: none), and the from-date given for each figure setting, by its key (none given: the
 * sheet's today), and whether the proof threshold is changed and to what (null: none), and the
 * actions whose entry in the permission matrix is changed, in matrix order, each to the roles that
 * may take it as a comma separated list ('' for the standing rule), and whether the grace days are
 * changed and to what (null: off), and whether the note threshold is changed and to what (null: none), and whether the entry date is
 * changed and to what (null: off), and the grades whose grace days are changed, in A, B, C order,
 * and to what (null: none), and the grades whose proof threshold is changed, in A, B, C order, and
 * to what (null: none), and whether the pot is changed and to what (null: none).
 */
public record SettingsInput(boolean clerkLimitChanged, BigDecimal clerkLimit, BigDecimal floor, Integer terms, BigDecimal latePct,
        boolean policyDateChanged, LocalDate policyDate,
        boolean periodNumberingFromChanged, LocalDate periodNumberingFrom,
        java.util.Map<String, Integer> gradeTerms, boolean capChanged, BigDecimal cap,
        java.util.Map<String, LocalDate> from, boolean proofThresholdChanged, BigDecimal proofThreshold,
        java.util.Map<String, String> perms, boolean graceDaysChanged, Integer graceDays,
        boolean noteThresholdChanged, BigDecimal noteThreshold,
        boolean entryDateChanged, LocalDate entryDate, java.util.Map<String, Integer> gradeGrace,
        java.util.Map<String, BigDecimal> gradeProofThreshold,
        boolean potChanged, BigDecimal pot) {

    /**
     * The figure settings being changed, by key in the order they are audited, each with the value
     * it is recorded as ('' for none).
     */
    public java.util.Map<String, String> datedValues() {
        java.util.Map<String, String> values = new java.util.LinkedHashMap<>();
        if (clerkLimitChanged) values.put(Settings.CLERK_LIMIT, clerkLimit == null ? "" : clerkLimit.toPlainString());
        if (floor != null) values.put(Settings.FLOOR, floor.toPlainString());
        if (terms != null) values.put(Settings.TERMS, terms.toString());
        if (latePct != null) values.put(Settings.LATE_PCT, latePct.toPlainString());
        return values;
    }

    /** The grades whose terms are changed, by key, each with the value it is recorded as ('' for the sheet's). */
    public java.util.Map<String, String> gradeTermsValues() {
        java.util.Map<String, String> values = new java.util.LinkedHashMap<>();
        gradeTerms.forEach((grade, days) -> values.put(Settings.gradeTermsKey(grade), days == null ? "" : days.toString()));
        return values;
    }

    /** The grades whose grace days are changed, by key, each with the value it is recorded as ('' for none). */
    public java.util.Map<String, String> gradeGraceValues() {
        java.util.Map<String, String> values = new java.util.LinkedHashMap<>();
        gradeGrace.forEach((grade, days) -> values.put(Settings.gradeGraceKey(grade), days == null ? "" : days.toString()));
        return values;
    }

    /** The grades whose proof threshold is changed, by key, each with the value it is recorded as ('' for none). */
    public java.util.Map<String, String> gradeProofThresholdValues() {
        java.util.Map<String, String> values = new java.util.LinkedHashMap<>();
        gradeProofThreshold.forEach((grade, figure) ->
                values.put(Settings.gradeProofThresholdKey(grade), figure == null ? "" : figure.toPlainString()));
        return values;
    }

    /** The cap as it is recorded ('' for none), or null when it is not changed. */
    public String capValue() {
        return !capChanged ? null : cap == null ? "" : cap.toPlainString();
    }

    /** The proof threshold as it is recorded ('' for none), or null when it is not changed. */
    public String proofThresholdValue() {
        return !proofThresholdChanged ? null : proofThreshold == null ? "" : proofThreshold.toPlainString();
    }

    /** The note threshold as it is recorded ('' for none), or null when it is not changed. */
    public String noteThresholdValue() {
        return !noteThresholdChanged ? null : noteThreshold == null ? "" : noteThreshold.toPlainString();
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;

/**
 * A sheet's settings. The figure settings are dated ({@code dated}, by key, each value from a
 * from-date; a blank value is "none"): its clerk limit, the highest due a clerk may settle (none: no
 * limit), its floor, the least a claim's live due may be, and its terms, the days after a claim's
 * date that it is due by, and its late percent, what an overdue claim's due gains per full 30 days
 * overdue, and its terms per grade (a grade with none uses the sheet's terms), and its cap (none:
 * no cap), the most a person's due-total may be, and its proof threshold (none: none), above which a
 * claim's due, on the claim's date, needs a proof before it is settled or approved, and its note
 * threshold (none: none), above which a claim's due, on the claim's date, needs a note before it is opened, and
 * its proof threshold per grade (none: the sheet's proof threshold). The value in force on a date is the one with the
 * latest from-date on or before it; before every from-date the starting value (floor 1.00, late
 * percent 0.00, terms 14; none for the others). A claim takes its floor, late percent and terms on
 * its date; the clerk limit and the cap are those in force on the sheet's today ({@code today}).
 * Not dated: its policy date (null: the sheet's today): a claim dated before it rounds half up, one
 * on or after it half to even, and its period numbering from (null: off): while the sheet's today
 * is on or after it, a claim opened is numbered within its period, and its permission matrix
 * ({@code perms}, by action, the roles that may take it as a comma separated list; blank or missing:
 * the standing rule, open, settle, void and close by clerk and steward, reassign and reopen by steward),
 * and its grace days (null: off): when the sheet's today is changed, every open period whose to-date
 * plus the grace days is before the new today is closed, and its entry date (null: off): while it is
 * set, the date of a new claim left undated instead of the sheet's today, and its pot (null: none),
 * shared out as cuts among a balanced pool's members.
 */
public record Settings(String sheetId, LocalDate today, Map<String, NavigableMap<LocalDate, String>> dated,
        LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, String> perms, Integer graceDays,
        LocalDate entryDate, BigDecimal pot) {
    /** The grades that may have their own terms. */
    public static final List<String> GRADES = List.of("A", "B", "C");

    public static final String CLERK_LIMIT = "clerk-limit";
    public static final String FLOOR = "floor";
    public static final String TERMS = "terms";
    public static final String LATE_PCT = "late-pct";
    public static final String CAP = "cap";
    public static final String PROOF_THRESHOLD = "proof-threshold";
    public static final String NOTE_THRESHOLD = "note-threshold";

    /** The actions of the permission matrix, in the order they are shown and audited. */
    public static final List<String> ACTIONS = List.of("open", "settle", "void", "reassign", "close", "reopen");

    /** The key of an action's entry in the permission matrix. */
    public static String permKey(String action) {
        return "perm-" + action;
    }

    /** The roles that may take an action by the standing rule. */
    public static List<String> standingRoles(String action) {
        return "reassign".equals(action) || "reopen".equals(action) ? List.of("steward") : List.of("clerk", "steward");
    }

    /** The roles that may take an action: its entry in the permission matrix, else the standing rule. */
    public List<String> rolesFor(String action) {
        String entry = perms == null ? null : perms.get(action);
        if (entry == null || entry.isBlank()) return standingRoles(action);
        return java.util.Arrays.stream(entry.split(",")).map(String::trim).filter((r) -> !r.isEmpty()).toList();
    }

    /** Whether a role may take an action. */
    public boolean allows(String action, String role) {
        if (net.officefloor.hq.app.role.Role.VIEWER.equals(role)) return false; // a viewer changes nothing
        return rolesFor(action).contains(role);
    }

    /** The key of a grade's own terms. */
    public static String gradeTermsKey(String grade) {
        return "terms-" + grade;
    }

    /** The key of a grade's grace days. */
    public static String gradeGraceKey(String grade) {
        return "grace-" + grade;
    }

    /** The key of a grade's own proof threshold. */
    public static String gradeProofThresholdKey(String grade) {
        return "proof-threshold-" + grade;
    }

    /** A grade's own proof threshold in force on a date, or null when it has none. */
    public BigDecimal gradeProofThresholdOn(String grade, LocalDate date) {
        return figureOn(gradeProofThresholdKey(grade), date);
    }

    /** A grade's grace days in force on a date, or null when it has none. */
    public Integer gradeGraceOn(String grade, LocalDate date) {
        String value = valueOn(gradeGraceKey(grade), date);
        return value == null || value.isEmpty() ? null : Integer.valueOf(value);
    }

    /**
     * The day a claim's overdue count starts from: its due-by plus the grace days of its grade (the
     * one in force on its date) in force on its date, or its due-by when that grade has none. A
     * claim is overdue when this is before the sheet's today, and its late charge's 30-day
     * boundaries are counted from it.
     */
    public LocalDate overdueFrom(LocalDate dueBy, String grade, LocalDate date) {
        Integer grace = grade == null ? null : gradeGraceOn(grade, date);
        return grace == null ? dueBy : dueBy.plusDays(grace);
    }

    /** A sheet's floor until it is set. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** A sheet's terms until they are set. */
    public static final int DEFAULT_TERMS = 14;

    /** A sheet's late percent until it is set. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    /** The value of a key in force on a date: null when none is recorded on or before it, '' for none. */
    public String valueOn(String key, LocalDate date) {
        NavigableMap<LocalDate, String> values = dated.get(key);
        if (values == null || date == null) return null;
        Map.Entry<LocalDate, String> entry = values.floorEntry(date);
        return entry == null ? null : entry.getValue();
    }

    private BigDecimal figureOn(String key, LocalDate date) {
        String value = valueOn(key, date);
        return value == null || value.isEmpty() ? null : new BigDecimal(value).setScale(2);
    }

    /** The floor in force on a date. */
    public BigDecimal floorOn(LocalDate date) {
        BigDecimal floor = figureOn(FLOOR, date);
        return floor != null ? floor : DEFAULT_FLOOR;
    }

    /** The late percent in force on a date. */
    public BigDecimal latePctOn(LocalDate date) {
        BigDecimal pct = figureOn(LATE_PCT, date);
        return pct != null ? pct : DEFAULT_LATE_PCT;
    }

    /** The sheet's terms in force on a date. */
    public int termsOn(LocalDate date) {
        String value = valueOn(TERMS, date);
        return value == null || value.isEmpty() ? DEFAULT_TERMS : Integer.parseInt(value);
    }

    /** A grade's own terms in force on a date, or null when it takes the sheet's. */
    public Integer gradeTermsOn(String grade, LocalDate date) {
        String value = valueOn(gradeTermsKey(grade), date);
        return value == null || value.isEmpty() ? null : Integer.valueOf(value);
    }

    /** The terms of a person's claim on a date: their own, else their grade's then, else the sheet's. */
    public int termsFor(net.officefloor.hq.app.person.Person person, LocalDate date) {
        Integer own = person.getTerms();
        return own != null ? own : termsFor(person.gradeOn(date), date);
    }

    /** The terms of a grade on a date: its own, else the sheet's. */
    public int termsFor(String grade, LocalDate date) {
        Integer own = gradeTermsOn(grade, date);
        return own != null ? own : termsOn(date);
    }

    /** The clerk limit in force on a date (null: no limit). */
    public BigDecimal clerkLimitOn(LocalDate date) {
        return figureOn(CLERK_LIMIT, date);
    }

    /** The proof threshold in force on a date (null: none). */
    public BigDecimal proofThresholdOn(LocalDate date) {
        return figureOn(PROOF_THRESHOLD, date);
    }

    /**
     * The proof threshold of a claim of a grade dated {@code date}: the grade's own in force on that
     * date when it has one, else the sheet's (null: none).
     */
    public BigDecimal proofThresholdFor(String grade, LocalDate date) {
        BigDecimal own = grade == null ? null : gradeProofThresholdOn(grade, date);
        return own != null ? own : proofThresholdOn(date);
    }

    /**
     * Whether a claim of a grade dated {@code date} with a due (null: n/a) and a proofs count needs
     * a proof before it is settled or approved: its due is above its proof threshold and it has no
     * proofs. A due of n/a, or no threshold, needs none.
     */
    public boolean needsProof(BigDecimal due, String grade, LocalDate date, int proofs) {
        BigDecimal threshold = proofThresholdFor(grade, date);
        return proofs == 0 && threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** The note threshold in force on a date (null: none). */
    public BigDecimal noteThresholdOn(LocalDate date) {
        return figureOn(NOTE_THRESHOLD, date);
    }

    /**
     * Whether a claim dated {@code date} with a due (null: n/a) and a note needs a note before it is
     * opened: its due is above the note threshold in force on its date and its note is empty. A due
     * of n/a, or no threshold, needs none.
     */
    public boolean needsNote(BigDecimal due, LocalDate date, String note) {
        BigDecimal threshold = noteThresholdOn(date);
        return (note == null || note.isBlank()) && threshold != null && due != null && due.compareTo(threshold) > 0;
    }

    /** The cap in force on a date (null: none). */
    public BigDecimal capOn(LocalDate date) {
        return figureOn(CAP, date);
    }

    /**
     * How every figure of a claim that rounds by {@code date} is rounded: half up before the policy
     * date ({@code today} when it is blank), half to even on or after it.
     */
    public RoundingMode rounding(LocalDate date, LocalDate today) {
        LocalDate policy = policyDate != null ? policyDate : today;
        return date.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** The date of a new claim left undated: the entry date while it is set, else the sheet's today. */
    public LocalDate entryDay(LocalDate today) {
        return entryDate != null ? entryDate : today;
    }

    /** Whether a period ending {@code to} is past its grace days on {@code today}: never while they are off. */
    public boolean pastGrace(LocalDate to, LocalDate today) {
        return graceDays != null && to.plusDays(graceDays).isBefore(today);
    }

    /** Whether a claim opened on {@code today} is numbered within its period. */
    public boolean numbersByPeriod(LocalDate today) {
        return periodNumberingFrom != null && !today.isBefore(periodNumberingFrom);
    }

    /** A person's due-total (null: n/a) held to the cap in force on {@code today}. A due-total of n/a is not capped. */
    public BigDecimal capped(BigDecimal dueTotal, LocalDate today) {
        BigDecimal cap = capOn(today);
        return cap == null || dueTotal == null || dueTotal.compareTo(cap) <= 0 ? dueTotal : cap;
    }

    /** Whether a due (null: n/a) is within the clerk limit in force on {@code today}. A due of n/a is within any limit. */
    public boolean withinClerkLimit(BigDecimal due, LocalDate today) {
        BigDecimal clerkLimit = clerkLimitOn(today);
        return clerkLimit == null || due == null || due.compareTo(clerkLimit) <= 0;
    }
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.NavigableMap;
import java.util.TreeMap;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowCallbackHandler;
import org.springframework.stereotype.Repository;

/** The settings store: the dated values in setting_value, the undated ones on the sheet's row. */
@Repository
public class SettingsRepository {

    private final JdbcTemplate jdbc;

    public SettingsRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public Settings find(String sheetId) {
        Map<String, NavigableMap<LocalDate, String>> dated = new HashMap<>();
        jdbc.query("SELECT setting_key, from_date, setting_value FROM setting_value WHERE sheet_id = ?",
                (RowCallbackHandler) (rs) -> dated.computeIfAbsent(rs.getString("setting_key"), (k) -> new TreeMap<>())
                        .put(rs.getDate("from_date").toLocalDate(), rs.getString("setting_value")), sheetId);
        Map<String, String> perms = new HashMap<>();
        jdbc.query("SELECT action, roles FROM setting_perm WHERE sheet_id = ?",
                (RowCallbackHandler) (rs) -> perms.put(rs.getString("action"), rs.getString("roles")), sheetId);
        List<Settings> found = jdbc.query("SELECT today, policy_date, period_numbering_from, grace_days, entry_date, pot FROM sheet WHERE id = ?",
                (rs, n) -> new Settings(sheetId, rs.getDate("today").toLocalDate(), dated,
                        rs.getDate("policy_date") == null ? null : rs.getDate("policy_date").toLocalDate(),
                        rs.getDate("period_numbering_from") == null ? null : rs.getDate("period_numbering_from").toLocalDate(), perms,
                        rs.getObject("grace_days", Integer.class),
                        rs.getDate("entry_date") == null ? null : rs.getDate("entry_date").toLocalDate(),
                        rs.getBigDecimal("pot")),
                sheetId);
        return found.isEmpty() ? new Settings(sheetId, null, dated, null, null, perms, null, null, null) : found.get(0);
    }

    /** Records a dated setting's value from a date, replacing any value already recorded from it. */
    public void record(String sheetId, String key, LocalDate from, String value) {
        jdbc.update("MERGE INTO setting_value (sheet_id, setting_key, from_date, setting_value) KEY (sheet_id, setting_key, from_date) VALUES (?, ?, ?, ?)",
                sheetId, key, java.sql.Date.valueOf(from), value);
        history(sheetId, key, from, value);
    }

    /** Keeps a setting's value in its history, with the sheet's today now. */
    private void history(String sheetId, String key, LocalDate from, String value) {
        jdbc.update("INSERT INTO setting_history (sheet_id, setting_key, from_date, setting_value, set_on)"
                + " VALUES (?, ?, ?, ?, (SELECT today FROM sheet WHERE id = ?))",
                sheetId, key, from == null ? null : java.sql.Date.valueOf(from), value, sheetId);
    }

    /**
     * The sheet's settings as they stood at the end of {@code day}: each dated value and the policy
     * date as last recorded while the sheet's today was on or before it, and that date standing in for
     * the sheet's today. The others are as they are now.
     */
    public Settings findAsOf(String sheetId, LocalDate day) {
        Settings now = find(sheetId);
        Map<String, NavigableMap<LocalDate, String>> dated = new HashMap<>();
        LocalDate[] policy = { null };
        boolean[] policyKept = { false };
        jdbc.query("SELECT setting_key, from_date, setting_value, set_on FROM setting_history WHERE sheet_id = ? ORDER BY id",
                (RowCallbackHandler) (rs) -> {
                    String key = rs.getString("setting_key");
                    String value = rs.getString("setting_value");
                    boolean counts = !rs.getDate("set_on").toLocalDate().isAfter(day);
                    if (POLICY_DATE.equals(key)) {
                        policyKept[0] = true;
                        if (counts) policy[0] = value.isBlank() ? null : LocalDate.parse(value);
                    } else if (counts) {
                        dated.computeIfAbsent(key, (k) -> new TreeMap<>()).put(rs.getDate("from_date").toLocalDate(), value);
                    }
                }, sheetId);
        return new Settings(sheetId, day, dated, policyKept[0] ? policy[0] : now.policyDate(),
                now.periodNumberingFrom(), now.perms(), now.graceDays(), now.entryDate(), now.pot());
    }

    private static final String POLICY_DATE = "policy-date";

    /** Records the roles ('' for the standing rule) that may take an action. */
    public void recordPerm(String sheetId, String action, String roles) {
        jdbc.update("MERGE INTO setting_perm (sheet_id, action, roles) KEY (sheet_id, action) VALUES (?, ?, ?)",
                sheetId, action, roles);
    }

    /** Saves the undated settings. */
    public void saveUndated(Settings settings) {
        jdbc.update("UPDATE sheet SET policy_date = ?, period_numbering_from = ?, grace_days = ?, entry_date = ?, pot = ? WHERE id = ?",
                settings.policyDate() == null ? null : java.sql.Date.valueOf(settings.policyDate()),
                settings.periodNumberingFrom() == null ? null : java.sql.Date.valueOf(settings.periodNumberingFrom()),
                settings.graceDays(),
                settings.entryDate() == null ? null : java.sql.Date.valueOf(settings.entryDate()),
                settings.pot(), settings.sheetId());
        history(settings.sheetId(), POLICY_DATE, null,
                settings.policyDate() == null ? "" : settings.policyDate().toString());
    }
}
package net.officefloor.hq.app.setting;

/**
 * Settings as the screen sends them, each only when it is being changed (null: left as it is): the
 * clerk limit, with up to two decimals (blank: no limit), the floor, with up to two decimals, and
 * the terms, a whole number of days, and the late percent, with up to two decimals, and the policy
 * date as yyyy-MM-dd (blank: the sheet's today), and the period numbering from as yyyy-MM-dd
 * (blank: off), and the terms of each grade being changed, a whole number of days (blank: the
 * sheet's terms), and the cap, with up to two decimals (blank: none), and the from-date of each
 * figure setting being changed, by its key (clerk-limit, floor, terms, late-pct, terms-A, terms-B,
 * terms-C, cap, proof-threshold, note-threshold), as yyyy-MM-dd (blank or missing: the sheet's today), and the proof
 * threshold, with up to two decimals (blank: none), and the entry of each action of the permission
 * matrix being changed, by action (open, settle, void, reassign, close, reopen), a comma separated
 * list of roles, clerk or steward (blank: the standing rule), and the grace days, a whole number of
 * days (blank: off), and the note threshold, with up to two decimals (blank: none), and the entry date as yyyy-MM-dd
 * (blank: off), and the grace days of each grade being changed, a whole number of days (blank:
 * none), dated by its key (grace-A, grace-B, grace-C), and the proof threshold of each grade being
 * changed, with up to two decimals (blank: none, the sheet's), dated by its key (proof-threshold-A,
 * proof-threshold-B, proof-threshold-C), and the pot, with up to two decimals (blank: none), not dated.
 */
public record SettingsRequest(String clerkLimit, String floor, String terms, String latePct, String policyDate, String periodNumberingFrom,
        java.util.Map<String, String> gradeTerms, String cap, java.util.Map<String, String> from,
        String proofThreshold, java.util.Map<String, String> perms, String graceDays, String noteThreshold,
        String entryDate, java.util.Map<String, String> gradeGrace,
        java.util.Map<String, String> gradeProofThreshold, String pot) {
}
package net.officefloor.hq.app.setting;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * A sheet's settings, as the screen reads them, each figure setting as it is in force on the sheet's
 * today: the clerk limit with two decimals ('' for none), the floor with two decimals, the terms in
 * days and the late percent with two decimals, and the policy date as yyyy-MM-dd ('' for the sheet's
 * today), and the period numbering from as yyyy-MM-dd ('' for off), and each grade's own terms in
 * days ('' for the sheet's terms), and the cap with two decimals ('' for none); and every value
 * recorded for each figure setting, by key, in from-date order; and the proof threshold with two
 * decimals ('' for none); and each action's entry in the permission matrix, in matrix order, as
 * saved ('' for the standing rule); and the grace days ('' for off); and the note threshold with two
 * decimals ('' for none); and the entry date as yyyy-MM-dd ('' for off); and each grade's grace
 * days ('' for none); and each grade's proof threshold with two decimals ('' for none); and the pot
 * with two decimals ('' for none).
 */
public record SettingsResponse(String clerkLimit, String floor, String terms, String latePct, String policyDate,
        String periodNumberingFrom, Map<String, String> gradeTerms, String cap, Map<String, List<Dated>> dated,
        String proofThreshold, Map<String, String> perms, String graceDays, String noteThreshold,
        String entryDate, Map<String, String> gradeGrace, Map<String, String> gradeProofThreshold,
        String pot) {

    /** A value ('' for none) recorded from a date (yyyy-MM-dd). */
    public record Dated(String from, String value) {
    }

    public static SettingsResponse from(Settings settings) {
        LocalDate today = settings.today();
        return new SettingsResponse(show(settings.clerkLimitOn(today)),
                show(settings.floorOn(today)), Integer.toString(settings.termsOn(today)),
                show(settings.latePctOn(today)),
                settings.policyDate() == null ? "" : settings.policyDate().toString(),
                settings.periodNumberingFrom() == null ? "" : settings.periodNumberingFrom().toString(),
                gradeTerms(settings),
                show(settings.capOn(today)),
                dated(settings),
                show(settings.proofThresholdOn(today)),
                perms(settings),
                settings.graceDays() == null ? "" : settings.graceDays().toString(),
                show(settings.noteThresholdOn(today)),
                settings.entryDate() == null ? "" : settings.entryDate().toString(),
                gradeGrace(settings),
                gradeProofThreshold(settings),
                show(settings.pot()));
    }

    private static String show(java.math.BigDecimal figure) {
        return figure == null ? "" : figure.setScale(2).toPlainString();
    }

    private static Map<String, String> gradeTerms(Settings settings) {
        Map<String, String> shown = new LinkedHashMap<>();
        for (String grade : Settings.GRADES) {
            Integer own = settings.gradeTermsOn(grade, settings.today());
            shown.put(grade, own == null ? "" : own.toString());
        }
        return shown;
    }

    private static Map<String, String> gradeGrace(Settings settings) {
        Map<String, String> shown = new LinkedHashMap<>();
        for (String grade : Settings.GRADES) {
            Integer grace = settings.gradeGraceOn(grade, settings.today());
            shown.put(grade, grace == null ? "" : grace.toString());
        }
        return shown;
    }

    private static Map<String, String> gradeProofThreshold(Settings settings) {
        Map<String, String> shown = new LinkedHashMap<>();
        for (String grade : Settings.GRADES) shown.put(grade, show(settings.gradeProofThresholdOn(grade, settings.today())));
        return shown;
    }

    private static Map<String, String> perms(Settings settings) {
        Map<String, String> shown = new LinkedHashMap<>();
        for (String action : Settings.ACTIONS) {
            String roles = settings.perms() == null ? null : settings.perms().get(action);
            shown.put(action, roles == null ? "" : roles);
        }
        return shown;
    }

    private static Map<String, List<Dated>> dated(Settings settings) {
        Map<String, List<Dated>> shown = new LinkedHashMap<>();
        settings.dated().forEach((key, values) -> {
            List<Dated> list = new ArrayList<>();
            values.forEach((from, value) -> list.add(new Dated(from.toString(), value)));
            shown.put(key, list);
        });
        return shown;
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Pattern;
import net.officefloor.hq.app.role.Role;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateSettings {
    private static final Pattern FIGURE = Pattern.compile("\\d{1,15}(\\.\\d{1,2})?");
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");
    private static final java.util.Set<String> DATED = java.util.Set.of(Settings.CLERK_LIMIT, Settings.FLOOR,
            Settings.TERMS, Settings.LATE_PCT, Settings.CAP, Settings.gradeTermsKey("A"), Settings.gradeTermsKey("B"),
            Settings.gradeTermsKey("C"), Settings.PROOF_THRESHOLD, Settings.NOTE_THRESHOLD,
            Settings.gradeGraceKey("A"), Settings.gradeGraceKey("B"), Settings.gradeGraceKey("C"),
            Settings.gradeProofThresholdKey("A"), Settings.gradeProofThresholdKey("B"),
            Settings.gradeProofThresholdKey("C"));

    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> body)
            throws InvalidSettingException {
        boolean limitChanged = request != null && request.clerkLimit() != null;
        BigDecimal limit = null;
        if (limitChanged && !request.clerkLimit().trim().isEmpty()) {
            String value = request.clerkLimit().trim();
            if (!FIGURE.matcher(value).matches()) {
                throw new InvalidSettingException("A clerk limit is 0.00 or more, with up to two decimals");
            }
            limit = new BigDecimal(value).setScale(2);
        }
        BigDecimal floor = null;
        if (request != null && request.floor() != null) {
            String value = request.floor().trim();
            if (!FIGURE.matcher(value).matches()) {
                throw new InvalidSettingException("A floor is 0.00 or more, with up to two decimals");
            }
            floor = new BigDecimal(value).setScale(2);
        }
        Integer terms = null;
        if (request != null && request.terms() != null) {
            String value = request.terms().trim();
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSettingException("Terms are a whole number of days, 0 or more");
            }
            terms = Integer.valueOf(value);
        }
        BigDecimal latePct = null;
        if (request != null && request.latePct() != null) {
            String value = request.latePct().trim();
            if (!FIGURE.matcher(value).matches()) {
                throw new InvalidSettingException("A late percent is 0.00 or more, with up to two decimals");
            }
            latePct = new BigDecimal(value).setScale(2);
        }
        boolean policyChanged = request != null && request.policyDate() != null;
        LocalDate policyDate = null;
        if (policyChanged && !request.policyDate().trim().isEmpty()) {
            try {
                policyDate = LocalDate.parse(request.policyDate().trim());
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("A policy date is a date, yyyy-MM-dd, or blank");
            }
        }
        boolean numberingChanged = request != null && request.periodNumberingFrom() != null;
        LocalDate numberingFrom = null;
        if (numberingChanged && !request.periodNumberingFrom().trim().isEmpty()) {
            try {
                numberingFrom = LocalDate.parse(request.periodNumberingFrom().trim());
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("A period numbering from is a date, yyyy-MM-dd, or blank");
            }
        }
        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
        if (request != null && request.gradeTerms() != null) {
            for (String grade : request.gradeTerms().keySet()) {
                if (!Settings.GRADES.contains(grade)) throw new InvalidSettingException("A grade is one of A, B or C");
            }
            for (String grade : Settings.GRADES) {
                String value = request.gradeTerms().get(grade);
                if (value == null) continue;
                value = value.trim();
                if (value.isEmpty()) {
                    gradeTerms.put(grade, null);
                } else if (!DAYS.matcher(value).matches()) {
                    throw new InvalidSettingException("Terms are a whole number of days, 0 or more, or blank");
                } else {
                    gradeTerms.put(grade, Integer.valueOf(value));
                }
            }
        }
        Map<String, Integer> gradeGrace = new LinkedHashMap<>();
        if (request != null && request.gradeGrace() != null) {
            for (String grade : request.gradeGrace().keySet()) {
                if (!Settings.GRADES.contains(grade)) throw new InvalidSettingException("A grade is one of A, B or C");
            }
            for (String grade : Settings.GRADES) {
                String value = request.gradeGrace().get(grade);
                if (value == null) continue;
                value = value.trim();
                if (value.isEmpty()) {
                    gradeGrace.put(grade, null);
                } else if (!DAYS.matcher(value).matches()) {
                    throw new InvalidSettingException("Grace days are a whole number of days, 0 or more, or blank");
                } else {
                    gradeGrace.put(grade, Integer.valueOf(value));
                }
            }
        }
        Map<String, BigDecimal> gradeProofThreshold = new LinkedHashMap<>();
        if (request != null && request.gradeProofThreshold() != null) {
            for (String grade : request.gradeProofThreshold().keySet()) {
                if (!Settings.GRADES.contains(grade)) throw new InvalidSettingException("A grade is one of A, B or C");
            }
            for (String grade : Settings.GRADES) {
                String value = request.gradeProofThreshold().get(grade);
                if (value == null) continue;
                value = value.trim();
                if (value.isEmpty()) {
                    gradeProofThreshold.put(grade, null);
                } else if (!FIGURE.matcher(value).matches()) {
                    throw new InvalidSettingException("A proof threshold is 0.00 or more, with up to two decimals, or blank");
                } else {
                    gradeProofThreshold.put(grade, new BigDecimal(value).setScale(2));
                }
            }
        }
        boolean capChanged = request != null && request.cap() != null;
        BigDecimal cap = null;
        if (capChanged && !request.cap().trim().isEmpty()) {
            String value = request.cap().trim();
            if (!FIGURE.matcher(value).matches()) {
                throw new InvalidSettingException("A cap is 0.00 or more, with up to two decimals, or blank");
            }
            cap = new BigDecimal(value).setScale(2);
        }
        boolean thresholdChanged = request != null && request.proofThreshold() != null;
        BigDecimal threshold = null;
        if (thresholdChanged && !request.proofThreshold().trim().isEmpty()) {
            String value = request.proofThreshold().trim();
            if (!FIGURE.matcher(value).matches()) {
                throw new InvalidSettingException("A proof threshold is 0.00 or more, with up to two decimals, or blank");
            }
            threshold = new BigDecimal(value).setScale(2);
        }
        boolean noteThresholdChanged = request != null && request.noteThreshold() != null;
        BigDecimal noteThreshold = null;
        if (noteThresholdChanged && !request.noteThreshold().trim().isEmpty()) {
            String value = request.noteThreshold().trim();
            if (!FIGURE.matcher(value).matches()) {
                throw new InvalidSettingException("A note threshold is 0.00 or more, with up to two decimals, or blank");
            }
            noteThreshold = new BigDecimal(value).setScale(2);
        }
        Map<String, String> perms = new LinkedHashMap<>();
        if (request != null && request.perms() != null) {
            for (String action : request.perms().keySet()) {
                if (!Settings.ACTIONS.contains(action)) {
                    throw new InvalidSettingException("An action is one of " + String.join(", ", Settings.ACTIONS));
                }
            }
            for (String action : Settings.ACTIONS) {
                String value = request.perms().get(action);
                if (value == null) continue;
                value = value.trim();
                java.util.List<String> roles = new java.util.ArrayList<>();
                if (!value.isEmpty()) {
                    for (String role : value.split(",", -1)) {
                        role = role.trim();
                        if (!Role.CLERK.equals(role) && !Role.STEWARD.equals(role)) {
                            throw new InvalidSettingException("Roles are clerk or steward, separated by commas, or blank");
                        }
                        if (!roles.contains(role)) roles.add(role);
                    }
                }
                perms.put(action, String.join(",", roles));
            }
        }
        boolean graceChanged = request != null && request.graceDays() != null;
        Integer graceDays = null;
        if (graceChanged && !request.graceDays().trim().isEmpty()) {
            String value = request.graceDays().trim();
            if (!DAYS.matcher(value).matches()) {
                throw new InvalidSettingException("Grace days are a whole number of days, 0 or more, or blank");
            }
            graceDays = Integer.valueOf(value);
        }
        boolean entryChanged = request != null && request.entryDate() != null;
        LocalDate entryDate = null;
        if (entryChanged && !request.entryDate().trim().isEmpty()) {
            try {
                entryDate = LocalDate.parse(request.entryDate().trim());
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("An entry date is a date, yyyy-MM-dd, or blank");
            }
        }
        boolean potChanged = request != null && request.pot() != null;
        BigDecimal pot = null;
        if (potChanged && !request.pot().trim().isEmpty()) {
            String value = request.pot().trim();
            if (!FIGURE.matcher(value).matches()) {
                throw new InvalidSettingException("A pot is 0.00 or more, with up to two decimals, or blank");
            }
            pot = new BigDecimal(value).setScale(2);
        }
        Map<String, LocalDate> from = new LinkedHashMap<>();
        if (request != null && request.from() != null) {
            for (Map.Entry<String, String> entry : request.from().entrySet()) {
                if (!DATED.contains(entry.getKey())) throw new InvalidSettingException("Only a figure setting has a from-date");
                String value = entry.getValue() == null ? "" : entry.getValue().trim();
                if (value.isEmpty()) continue;
                try {
                    from.put(entry.getKey(), LocalDate.parse(value));
                } catch (DateTimeParseException e) {
                    throw new InvalidSettingException("A from-date is a date, yyyy-MM-dd, or blank");
                }
            }
        }
        body.set(new SettingsInput(limitChanged, limit, floor, terms, latePct, policyChanged, policyDate,
                numberingChanged, numberingFrom, gradeTerms, capChanged, cap, from,
                thresholdChanged, threshold, perms, graceChanged, graceDays, noteThresholdChanged, noteThreshold,
                entryChanged, entryDate, gradeGrace, gradeProofThreshold, potChanged, pot));
    }
}
# Save a sheet's settings. Validate first so a bad value is a 400, not a 404.
# A viewer may change nothing: refused before anything is read or written.
viewer:
  class: net.officefloor.hq.app.role.CheckCanChange
  next: validate
validate:
  class: net.officefloor.hq.app.setting.ValidateSettings
  next: load
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ transaction ]
  next: before
# The sheet's figures before the change, so the rollup lines tell which moved (the floor moves them).
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.setting.SaveSettings
  govern: [ transaction ]
  next: audit
# Last before the response: every rule has passed and the change is saved.
audit:
  class: net.officefloor.hq.app.setting.AuditSettingChanged
  govern: [ transaction ]
  next: rollup
# After the change's own lines: the figures it moved.
rollup:
  class: net.officefloor.hq.app.rollup.AuditRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.setting.RespondWithSettings
  govern: [ transaction ]

