test("parent sheet rates scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-04-05");
  expect(await ui.setRole(pg_uma, "wes", "steward")).toBe(true);
  await ui.setSetting(pg_uma, "late-pct", "5.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "terms-C", "3");
  await ui.setSetting(pg_uma, "perm-open", "steward");
  await ui.setSetting(pg_uma, "note-threshold", "1.00");
  expect(await ui.addHoliday(pg_uma, "2026-03-13")).toBe(true);
  await ui.setSetting(pg_uma, "proof-threshold-A", "4.00");
  expect(await ui.addVoidReason(pg_uma, "late")).toBe(true);
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  expect(await ui.saveTemplate(pg_uma, {"name": "T1", "amount": "99.95", "note": "tpl"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "10.00"})).toBe(true);
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "C", "contact": "ben@x"}));
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A", "contact": "ben@x"})).toBeNull();
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "contact": " Ada@x "}));
  expect(await ui.addPool(pg_uma, "P1")).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Cam", "share": "50.00"})).toBe(true);
  expect(await ui.addPoolMember(pg_uma, "P1", {"member": "Ben", "share": "50.00"})).toBe(true);
  expect(await ui.ratePreview(pg_uma, "C", "10.00")).toEqual({ count: 0, diff: "0.00" });
  const c_cam_0 = ui.must(await ui.addClaim(pg_uma, p_cam, {"amount": "10.25", "note": "n"}));
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.addAlias(pg_uma, p_ben, " ada ")).toBe(true);
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-03-01", "to": "2026-03-09"})).toBe(true);
  const pg_wes = await ui.userPage(browser, "wes", sheet);
  expect(await ui.reassign(pg_wes, c_cam_0, "Ben")).toBe(true);
  const c_cam_0_2 = ui.must(await ui.addClaim(pg_wes, p_cam, {"amount": "0.04", "date": "2026-03-28", "note": "n"}));
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0_2).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0_2).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0_2).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.02");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("rollup-claimed-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-overdue-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("rollup-overdue-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-settled-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("rollup-open-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("bulk-settle-batch")).toHaveText("");
  await expect(pg_wes.getByTestId("header-people-count")).toHaveText("2");
  await expect(pg_wes.getByTestId("header-claims-DRAFT-count")).toHaveText("2");
  await expect(pg_wes.getByTestId("header-claims-OPEN-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-PENDING-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-SETTLED-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-claims-VOID-count")).toHaveText("0");
  await expect(pg_wes.getByTestId("header-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("header-overdue-total")).toHaveText("0.00");
  expect(await ui.bulkGrade(pg_wes, [p_cam, p_ben], {"grade": "A"})).toBe(2);
  const c_cam_1 = ui.must(await ui.quickAdd(pg_wes, {"name": "Cam", "amount": "1.00"}, p_cam));
  await ui.refresh(pg_wes);
  expect(await ui.unstate(pg_wes, p_cam)).toBe(true);
  expect(await ui.statement(pg_wes, p_ben)).toBe(true);
  expect(await ui.setRate(pg_wes, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.statementAsOf(pg_wes, p_cam, "2026-02-25")).toBe(false);
  const c_cam_2 = ui.must(await ui.addClaim(pg_wes, p_cam, {"amount": "1.00", "date": "2026-03-01", "note": "n"}));
  await ui.refresh(pg_wes);
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_cam).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_2).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_1).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0_2).getByTestId("claim-due")).toHaveText("1.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0_2).getByTestId("claim-status")).toHaveText("DRAFT");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0_2).getByTestId("claim-stated")).toHaveText("no");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-claimed")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("person-row-" + p_ben).getByTestId("person-due-total")).toHaveText("0.00");
  await expect(pg_wes.getByTestId("claim-row-" + c_cam_0).getByTestId("claim-due")).toHaveText("1.02");
